<?php
require_once __DIR__ . '/config.php';send_cors_headers();$data=json_input();$username=value($data,'username');$current=value($data,'current_password');$new=value($data,'new_password');if($username===''||$current===''||strlen($new)<8){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Complete all fields. New password must be at least 8 characters.']);exit;}$conn=db();$stmt=$conn->prepare('SELECT password FROM hr_accounts WHERE username=? LIMIT 1');$stmt->bind_param('s',$username);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$row||!password_verify($current,$row['password'])){http_response_code(401);echo json_encode(['success'=>false,'message'=>'Current password is incorrect.']);$conn->close();exit;}$hash=password_hash($new,PASSWORD_DEFAULT);$stmt=$conn->prepare('UPDATE hr_accounts SET password=? WHERE username=?');$stmt->bind_param('ss',$hash,$username);$stmt->execute();log_activity($conn,$username,'Password updated','HR account password changed');echo json_encode(['success'=>true,'message'=>'Password updated successfully.']);$stmt->close();$conn->close();
